// ============================ TEST MODE =====================================
// Flip TEST_MODE_FLAG to true ONLY while testing, and set it back to false.
//
// It is deliberately AND-ed with the execution mode below. A production run
// (the 15-minute Schedule Trigger) reports mode 'production', so even if this
// flag is left true by mistake, the scheduled sweep can NEVER bypass a send
// window or a prayer-time delay and message a real customer at 3am. Only a
// manual run from the editor can.
// ============================================================================
const TEST_MODE_FLAG = false;

const mode = $execution.mode;                 // 'test' (manual) | 'production'
const TEST_MODE = TEST_MODE_FLAG && mode !== 'production';

return [{ json: {
  test_mode: TEST_MODE,
  test_mode_flag: TEST_MODE_FLAG,
  execution_mode: mode,

  // Pagination cap (global standard #8: no unbounded pagination).
  batch_limit: 50,

  // Gap to the NEXT touch, in minutes, keyed by the touch just sent.
  // Live: touch 1 -> +24h, touch 2 -> +48h (spec 5: T+45min / T+24h / T+72h).
  // Test: 10-minute gaps so a full 3-touch sequence is observable in 20 min.
  next_gap_minutes: TEST_MODE ? { '1': 10, '2': 10 } : { '1': 1440, '2': 2880 },

  // Twilio failure back-off (spec 5: push +2h and retry next sweep).
  send_failure_backoff_minutes: TEST_MODE ? 5 : 120,

  // Static demo discount for touch 2 (locked decision #7 - dynamic codes are a
  // client upsell). MUST exist in the Shopify store before the M6 demo.
  discount_code: 'LAYLA10',

  store_name: 'Layla Boutique',
  slack_channel: '#leads'
} }];

const resp = $input.first().json;
const httpCode = (resp && resp.statusCode) ? resp.statusCode : 0;
const body = resp ? resp.body : null;

// A failed fetch is NOT "no carts are due" - it is an unknown state. Emit a
// single failure marker so it gets logged, and send nothing this sweep.
if (httpCode !== 200 || !Array.isArray(body)) {
  return [{ json: {
    _fetch_failed: true,
    status_code: httpCode,
    detail: JSON.stringify(body === null || body === undefined ? {} : body).slice(0, 300)
  } }];
}

// Genuinely nothing due: return zero items so the sweep ends silently.
// Logging every empty 15-minute sweep would write ~96 noise rows a day.
if (body.length === 0) return [];

return body.map(function (c, i) {
  return { json: Object.assign({}, c, {
    _fetch_failed: false,
    _queue_index: i + 1,
    _queue_size: body.length,
    touch_number: (c.touches_sent || 0) + 1
  }) };
});

const cart = $('Loop Over Carts').first().json;
const resp = $input.first().json;
const httpCode = (resp && resp.statusCode) ? resp.statusCode : 0;
const body = resp ? resp.body : null;

// THE FAIL-SAFE (locked decision #4). Three distinct states, never two:
//   converted        -> close the cart, no message
//   not_converted    -> proven safe to message
//   skip_api_failure -> UNKNOWN. Send nothing, retry next sweep.
// Shopify returns HTTP 200 with an `errors` array on a scope problem, so a
// naive check would read a permissions failure as "no orders found" and
// message a customer who already paid.
let outcome = 'skip_api_failure';
let detail = null;
let order = null;

if (httpCode === 200 && body && !body.errors && body.data && body.data.orders) {
  const edges = body.data.orders.edges || [];
  if (edges.length > 0) {
    outcome = 'converted';
    const n = edges[0].node || {};
    const money = (n.totalPriceSet && n.totalPriceSet.shopMoney) ? n.totalPriceSet.shopMoney : {};
    order = {
      id: n.id || null,
      name: n.name || null,
      amount: (money.amount !== undefined && money.amount !== null) ? Number(money.amount) : null,
      currency: money.currencyCode || cart.currency || null
    };
  } else {
    outcome = 'not_converted';
  }
} else if (body && body.errors) {
  detail = ('graphql_errors: ' + JSON.stringify(body.errors)).slice(0, 300);
} else {
  detail = ('http_' + httpCode + ' ' + JSON.stringify(body === null || body === undefined ? {} : body)).slice(0, 300);
}

// Honest attribution (locked decision #9): a cart that converted before we ever
// messaged it is NOT a recovery and must never be counted as one.
const closeStatus = (cart.touches_sent || 0) > 0 ? 'recovered' : 'converted_before_first_touch';

return [{ json: Object.assign({}, cart, {
  outcome: outcome,
  conversion_detail: detail,
  order: order,
  close_status: closeStatus
}) }];

const cart = $('Classify Conversion Result').first().json;
const cfg  = $('Set Sweep Config').first().json;

let sw = null;
try {
  const resp = $input.first().json;
  const arr = (resp && resp.body) ? resp.body : (Array.isArray(resp) ? resp : null);
  if (Array.isArray(arr) && arr[0]) sw = arr[0];
} catch (e) {}

// No send_windows row for this country (e.g. a US customer of a Gulf store).
// Case 1 defaulted to Asia/Dubai because every lead was MENA. Here that would
// apply Gulf quiet hours and a Fri-Sat weekend to a New York shopper, so we
// fall back to the CART's own timezone with neutral defaults instead.
// THREE cases, and the log has to tell them apart (M5.8):
//   send_windows_row       - a configured market, use its rules
//   cart_timezone_fallback - no row, but intake DID resolve the customer's tz
//   store_timezone_default - we do NOT know the customer's timezone. Intake's
//                            dial table covers the target markets plus GB/FR/US;
//                            anything else (a German shopper, say) leaves it
//                            null. We then message during the STORE's hours and
//                            SAY SO, rather than logging a customer timezone we
//                            never had. Surfaced by the M5.8 Haiku-fallback test.
const tzSource    = (sw && sw.timezone) ? 'send_windows_row'
                  : (cart.timezone ? 'cart_timezone_fallback' : 'store_timezone_default');
const tz          = (sw && sw.timezone) || cart.timezone || 'Asia/Dubai';
const weekendDays = (sw && Array.isArray(sw.weekend_days)) ? sw.weekend_days : (sw ? [5, 6] : [6, 0]);
const quietStart  = (sw && sw.quiet_hours_start) || '22:00:00';
const quietEnd    = (sw && sw.quiet_hours_end)   || '08:00:00';

const PRAYER = {
  AE:{city:'Dubai',country:'United Arab Emirates',method:16},
  SA:{city:'Riyadh',country:'Saudi Arabia',method:4},
  QA:{city:'Doha',country:'Qatar',method:10},
  KW:{city:'Kuwait City',country:'Kuwait',method:9},
  BH:{city:'Manama',country:'Bahrain',method:8},
  OM:{city:'Muscat',country:'Oman',method:4},
  EG:{city:'Cairo',country:'Egypt',method:5},
  JO:{city:'Amman',country:'Jordan',method:23},
  LB:{city:'Beirut',country:'Lebanon',method:2},
  MA:{city:'Casablanca',country:'Morocco',method:21}
};
const prayer = PRAYER[cart.country_code] || null;
const respectPrayer = (sw ? (sw.respect_prayer_times !== false) : false) && !!prayer;

const now = DateTime.now().setZone(tz);

function hm(t){ const p = (t || '00:00').toString().split(':'); return { h: parseInt(p[0]||'0',10), m: parseInt(p[1]||'0',10) }; }
const qs = hm(quietStart), qe = hm(quietEnd);
const sMin = qs.h*60 + qs.m, eMin = qe.h*60 + qe.m, nMin = now.hour*60 + now.minute;
let inQuiet;
if (sMin > eMin) inQuiet = (nMin >= sMin || nMin < eMin);   // window crosses midnight
else inQuiet = (nMin >= sMin && nMin < eMin);

const dow = now.weekday % 7;                                 // Luxon Mon=1..Sun=7 -> JS Sun=0..Sat=6
const isWeekend = weekendDays.includes(dow);

function nextOpen(d){
  let cand = d.set({ hour: qe.h, minute: qe.m, second: 0, millisecond: 0 });
  if (d > cand) cand = cand.plus({ days: 1 });
  let guard = 0;
  while (weekendDays.includes(cand.weekday % 7) && guard < 9){
    cand = cand.plus({ days: 1 }).set({ hour: qe.h, minute: qe.m, second: 0, millisecond: 0 });
    guard++;
  }
  return cand;
}

const resume = (!isWeekend && !inQuiet) ? now : nextOpen(now);
const windowDelayed = resume.toMillis() > now.toMillis() + 1000;

return [{ json: {
  timezone: tz,
  country_code: cart.country_code,
  send_window_source: tzSource,
  weekend_days: weekendDays,
  is_weekend: isWeekend,
  in_quiet_hours: inQuiet,
  window_delayed: windowDelayed,
  window_resume: resume.toISO(),
  respect_prayer_times: respectPrayer,
  prayer_city: prayer ? prayer.city : null,
  prayer_country: prayer ? prayer.country : null,
  prayer_method: prayer ? prayer.method : null,
  // Skip the aladhan call when the window already blocks us, when the country
  // opts out, or in test mode - one fewer external call per cart per sweep.
  needs_prayer_check: (!windowDelayed) && respectPrayer && !cfg.test_mode,
  test_mode: cfg.test_mode,
  now_local: now.toISO()
} }];

const ctx = $('Resolve Send Context').first().json;
const now = DateTime.now().setZone(ctx.timezone);

let prayerCheck = 'ok';
let delayed = false;
let resume = now;

let timings = null;
try {
  const data = $input.first().json;
  const d = (data && data.body) ? data.body : data;
  if (d && d.data && d.data.timings) timings = d.data.timings;
} catch (e) {}

if (!timings) {
  // aladhan unreachable. Do NOT block the send - a missing prayer calendar is
  // not a reason to withhold a transactional message, and the quiet-hours
  // window has already been enforced. Logged so it is visible in the digest.
  prayerCheck = 'unavailable';
} else {
  const names = ['Fajr','Dhuhr','Asr','Maghrib','Isha'];
  for (const n of names) {
    const t = timings[n];
    if (!t) continue;
    const parts = t.toString().slice(0,5).split(':');
    const pt = now.set({ hour: parseInt(parts[0],10), minute: parseInt(parts[1],10), second: 0, millisecond: 0 });
    if (Math.abs(now.diff(pt, 'minutes').minutes) <= 15) { delayed = true; break; }
  }
  if (delayed) { resume = now.plus({ minutes: 30 }); prayerCheck = 'delayed'; }
}

return [{ json: {
  prayer_check: prayerCheck,
  prayer_delayed: delayed,
  prayer_resume: delayed ? resume.toISO() : null
} }];

const cart = $('Classify Conversion Result').first().json;
const ctx  = $('Resolve Send Context').first().json;
const cfg  = $('Set Sweep Config').first().json;

// Resolve Prayer Delay only runs on one of the two branches.
let prayer = { prayer_check: 'skipped', prayer_delayed: false, prayer_resume: null };
try {
  const p = $('Resolve Prayer Delay').first();
  if (p && p.json) prayer = p.json;
} catch (e) {}

// TOUCH-1 AGE GUARD (M5.2b; decisions.md 2026-08-03 M3.6). A Shopify recovery
// link 302s to the store root until Shopify creates its AbandonedCheckout
// record (~10-11 min on this store), so touch 1 must never go to a cart younger
// than MIN_AGE_MINUTES - the message would arrive with a dead call-to-action.
// NOT bypassable by TEST_MODE: every other gate reason is a timing preference,
// this one is a correctness precondition. Compressing it does not speed a test
// up, it invalidates it. To test touch 1 now, backdate the cart's created_at.
const MIN_AGE_MINUTES = 15;
const touchNumber = (cart.touches_sent || 0) + 1;
let too_young = false;
let too_young_resume = null;
let cart_age_minutes = null;
if (touchNumber === 1 && cart.created_at) {
  const createdMs = Date.parse(cart.created_at);
  if (!isNaN(createdMs)) {
    cart_age_minutes = Math.round((Date.now() - createdMs) / 60000);
    if (cart_age_minutes < MIN_AGE_MINUTES) {
      too_young = true;
      too_young_resume = new Date(createdMs + 45 * 60000).toISOString();
    }
  }
}

const blocked = !!(ctx.window_delayed || prayer.prayer_delayed || too_young);

// Latest of the applicable resume times.
let resumeAt = null;
const cands = [];
if (ctx.window_delayed && ctx.window_resume) cands.push(ctx.window_resume);
if (prayer.prayer_delayed && prayer.prayer_resume) cands.push(prayer.prayer_resume);
if (too_young && too_young_resume) cands.push(too_young_resume);
for (const c of cands) {
  if (resumeAt === null || Date.parse(c) > Date.parse(resumeAt)) resumeAt = c;
}

const reasons = [];
if (ctx.in_quiet_hours) reasons.push('quiet_hours');
if (ctx.is_weekend) reasons.push('weekend');
if (prayer.prayer_delayed) reasons.push('prayer_time');
if (too_young) reasons.push('cart_too_young');

// The gate is always COMPUTED honestly; test mode only changes the ACTION, so a
// bypassed send still logs exactly what it would have done in production.
return [{ json: {
  gate_blocked: (blocked && !cfg.test_mode) || too_young,
  gate_would_block: blocked,
  gate_bypassed_by_test_mode: blocked && cfg.test_mode && !too_young,
  cart_too_young: too_young,
  cart_age_minutes: cart_age_minutes,
  gate_reason: reasons.join('+') || 'open',
  resume_at: resumeAt,
  timezone: ctx.timezone,
  now_local: ctx.now_local,
  send_window_source: ctx.send_window_source,
  in_quiet_hours: ctx.in_quiet_hours,
  is_weekend: ctx.is_weekend,
  prayer_check: prayer.prayer_check,
  // pending_verification means "we have not yet proven this cart was abandoned".
  // The Shopify check just proved it, so promote it even if we cannot send yet.
  next_status: cart.status === 'pending_verification' ? 'abandoned' : cart.status
} }];

const cart = $('Classify Conversion Result').first().json;
const cfg  = $('Set Sweep Config').first().json;
const touch = (cart.touches_sent || 0) + 1;

// Money formatting is deterministic (Hussein, 2026-08-04): Western digits,
// thousands separators, currency code AFTER the number, no pointless decimals.
// Done here rather than asked of the model - "42663000 LBP" is unreadable and a
// model asked to format numbers will drift between messages.
function fmtMoney(amount, currency) {
  const cur = String(currency || '').toUpperCase();
  if (amount === null || amount === undefined || amount === '') return cur;
  const n = Number(amount);
  if (!isFinite(n)) return String(amount) + (cur ? ' ' + cur : '');
  // Currencies with no minor unit in practice - LBP totals run to 8 digits.
  const ZERO_DECIMAL = ['LBP','IQD','JPY','KRW','VND','CLP','ISK','KWD_NO'];
  const zero = ZERO_DECIMAL.indexOf(cur) >= 0;
  const hasCents = Math.abs(n - Math.round(n)) > 0.004;
  const dp = (zero || !hasCents) ? 0 : 2;
  const s = n.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp });
  return cur ? (s + ' ' + cur) : s;
}
const total_display = fmtMoney(cart.cart_total, cart.currency);

// Register varies by market (Hussein, 2026-08-04). حضرتك is natural in Egypt and
// the Levant but reads slightly off in the Gulf, where formality is warmer and
// less honorific-heavy. The VARIABLE is formal-vs-informal; the expressions that
// carry it are market-specific, so the model is told which market it is writing
// for rather than being handed one honorific to use everywhere.
const LEVANT_EGYPT = ['LB','JO','SY','PS','EG'];
const GULF = ['AE','SA','QA','KW','BH','OM'];
const cc = String(cart.country_code || '').toUpperCase();
const register_zone = LEVANT_EGYPT.indexOf(cc) >= 0 ? 'levant_egypt'
                    : (GULF.indexOf(cc) >= 0 ? 'gulf' : 'other');

const REGISTER_NOTE = {
  levant_egypt: [
    'Market: Levant / Egypt. Address the customer as حضرتك - it is natural here.',
    'حضرتك IS REQUIRED: it must appear AT LEAST ONCE in the message body, on every',
    'touch including the short farewell of touch 3. A message without it is rejected',
    'and the customer receives a generic template instead. It just must not sit in',
    'the greeting beside the name - put it in the sentence about the cart or the order.',
    'حضرتك is a polite SECOND person: verbs after it stay 2nd person.',
    '  WRONG: حضرتك اختار العباية   (3rd masc)',
    '  WRONG: حضرتك اختارت العباية  (3rd fem)',
    '  RIGHT: حضرتك اخترت العباية   (2nd person)',
    'Do NOT weld an object pronoun onto that verb at all - name the items instead.',
    'Ruled by Hussein 2026-09-08, after both touches that day shipped the ya form:',
    '  WRONG: حضرتك تركتيهما في السلة   (ya carrier - dialect)',
    '  WRONG: حضرتك تركتِهما في السلة   (pronoun welded on)',
    '  RIGHT: حضرتك تركتِ حقيبة يد وعباية في السلة   (female)',
    '  RIGHT: حضرتك تركت حقيبة يد وعباية في السلة   (male)',
    'Do NOT use 2nd-person-feminine PRESENT forms either (تستخدمي / تستخدمين).',
    'Consequence for touch 2: do NOT command the customer to use the discount code.',
    'State that the code exists and is theirs to use. Reaching for the imperative is',
    'what breaks this rule every time.'
  ].join('\n'),
  gulf: [
    'Market: Gulf. Do NOT use حضرتك - it reads as Egyptian/Levantine here.',
    'Use warm, plain, formal Modern Standard Arabic. Khaleeji formality is warmer',
    'and less honorific-heavy: natural greetings such as حياك الله fit where they',
    'suit the sentence. Respectful but not stiff, and never أنت / أنتِ informality.'
  ].join('\n'),
  other: [
    'Market: outside Levant/Egypt/Gulf. Use plain, warm, formal Modern Standard',
    'Arabic. Do not use أنت / أنتِ or informal imperatives.'
  ].join('\n')
};

const items = Array.isArray(cart.cart_items) ? cart.cart_items : [];
const named = items.slice(0, 2).map(function (i) {
  return (i.title || 'item') + ' ×' + (i.quantity || 1);
});
const extra = items.length - named.length;
const itemsSummary = named.join('; ') + (extra > 0 ? ('; and ' + extra + ' more') : '');

const lang = ['ar','en','fr','mixed'].indexOf(cart.language) >= 0 ? cart.language : 'en';
const firstName = (cart.customer_first_name || '').toString().trim();

// ---------------------------------------------------------------------------
// A LATIN NAME INSIDE AN ARABIC MESSAGE - fixed 2026-09-08 on Hussein's report.
// Shopify stores whatever the shopper typed at checkout, which for this store is
// `Hussein` in Latin script. The MODEL transliterates it on its own, so a
// generated message read `مرحباً حسين` while the STATIC FALLBACK read
// `مرحباً Hussein` - the same customer greeted two different ways depending on
// whether the checker had degraded the message. Only the fallback was wrong.
//
// The Arabic spellings below are NOT invented here. Every one is lifted from the
// name lists already in workflow 01's `Detect Language And Timezone`, which
// shipped with the gender inference. An UNKNOWN name keeps its Latin script,
// which is exactly what arabic-master-reference.md section 5 requires: "if a
// Latin-script name can't be cleanly rendered, keep it in Latin script inside
// the Arabic sentence rather than mangling it". This is a lookup, never a
// transliteration engine.
//
// Applied only when the message language is Arabic, and only when the stored
// name is Latin - a name already in Arabic script is passed through untouched.
// [VET] the pairings are standard spellings but have not had Hussein's pass.
// ---------------------------------------------------------------------------
const AR_NAMES = {
    'mohammed':  'محمد',
    'mohamed':   'محمد',
    'muhammad':  'محمد',
    'mohammad':  'محمد',
    'ahmed':     'احمد',
    'ahmad':     'احمد',
    'ali':       'علي',
    'omar':      'عمر',
    'umar':      'عمر',
    'khaled':    'خالد',
    'khalid':    'خالد',
    'hassan':    'حسن',
    'hasan':     'حسن',
    'hussein':   'حسين',
    'hussain':   'حسين',
    'youssef':   'يوسف',
    'yousef':    'يوسف',
    'yusuf':     'يوسف',
    'ibrahim':   'ابراهيم',
    'abdullah':  'عبدالله',
    'abdallah':  'عبدالله',
    'mariam':    'مريم',
    'maryam':    'مريم',
    'layla':     'ليلى',
    'laila':     'ليلى',
    'leila':     'ليلى',
    'zeinab':    'زينب',
    'zainab':    'زينب',
    'rana':      'رنا',
    'reem':      'ريم',
    'rim':       'ريم',
    'hind':      'هند',
    'nada':      'ندى',
    'sahar':     'سحر',
    'dina':      'دينا'
};
const isLatin = /^[A-Za-z][A-Za-z'\- ]*$/.test(firstName);
const arName = AR_NAMES[firstName.toLowerCase()];
const arTarget = (lang === 'ar' || lang === 'mixed');
const displayName = (arTarget && isLatin && arName) ? arName : firstName;


// Gender agreement (arabic-master-reference.md section 5; ruled for Case 2 2026-08-07).
// Inferred once at INTAKE and sticky in the database, so the register cannot
// change between touch 1 and touch 3. NULL on carts predating the migration,
// which reads as 'unknown' - and 'unknown' is a real answer, not a failure:
// it asks for gender-neutral phrasing rather than a guess.
const gender = ['female','male'].indexOf(String(cart.customer_gender || '').toLowerCase()) >= 0
  ? String(cart.customer_gender).toLowerCase() : 'unknown';

const GENDER_NOTE = {
  female: [
    'Customer gender: FEMALE. Use feminine agreement.',
    'Use the FULL MSA feminine present forms, which KEEP the ن:',
    '  RIGHT: تستخدمين، تطلبين، ترغبين',
    '  WRONG: تستخدمي، تطلبي، ترغبي   (colloquial - the ن is dropped)',
    'Past tense: NEVER a ي. The 2nd-person feminine past is written bare with a',
    'final KASRA on the last letter, and takes no attached object pronoun.',
    '  RIGHT: حضرتك تركتِ / حضرتك اخترتِ',
    '  WRONG: حضرتك تركتي / حضرتك تركتيهما / حضرتك تركتِهما',
    'The kasra is the ONLY diacritic you may write. Every other short vowel is banned.',
    'Keep the final ت - it is part of the verb, not an ending to trim:',
    '  WRONG: حضرتك تركِ / حضرتك ترك   (3rd person)',
    '  RIGHT: حضرتك تركتِ'
  ].join('\n'),
  male: [
    'Customer gender: MALE. Use masculine agreement throughout (اخترت، طلبك).',
    'Past tense is bare and carries NO diacritic: حضرتك تركت.',
    '"Bare" means no ي and no vowel mark. It does NOT mean a shorter verb - the final ت is',
    'part of the 2nd-person form and dropping it makes it 3rd person:',
    '  WRONG: حضرتك ترك / حضرتك اختار   (3rd person)',
    '  RIGHT: حضرتك تركت / حضرتك اخترت',
    'Do not use any feminine forms, and never write a kasra.'
  ].join('\n'),
  unknown: [
    'Customer gender: UNKNOWN. Do NOT guess.',
    'Prefer phrasing that avoids gendered verbs and pronouns altogether:',
    '  السلة محفوظة · يمكن إتمام الطلب في أي وقت · الطلب بانتظاركم',
    'If a gendered form is genuinely unavoidable, use the masculine as the MSA default.'
  ].join('\n')
};

// prompts/touch-message-generator.md v8 - keep the two in sync.
const system = [
"You write ONE WhatsApp message from a MENA online store to a customer who added items to their",
"cart and left without completing checkout. You are a helpful shop assistant, not a marketer.",
"",
"Write in the customer's language (given as language = ar | en | fr | mixed):",
"- \"ar\"    Natural Modern Standard Arabic, adjusted to the customer's country.",
"- \"en\"    Natural, warm professional English.",
"- \"fr\"    Natural professional French.",
"- \"mixed\" Lead in Arabic; a light English touch is acceptable.",
"",
"Touch number decides the intent - this is the only thing that changes between touches:",
"- touch 1 (about an hour after they left): a helpful reminder, ZERO pressure. Their cart is",
"  saved. No discount, no urgency, no persuasion.",
"- touch 2 (next day): offer the discount code you are given, framed as a gift from the store,",
"  never as desperation and never as a countdown. State the code exactly as given.",
"- touch 3 (two days later): the GENTLEST of the three, not the hardest. It is a warm goodbye:",
"  say plainly that this is the last message about this cart, and that it stays saved if they",
"  change their mind. The escalation in this sequence is the OFFER in touch 2, never the tone.",
"  No fake scarcity, no invented stock levels, no invented deadlines, no guilt, no pressure.",
"",
"The message MUST:",
"1. Greet the customer by first name if one is given; otherwise a warm neutral greeting.",
