const user = [
'Store: ' + cfg.store_name,
'Customer:',
'- first_name: ' + (displayName || '(none)'),
'- language: ' + lang,
'- country: ' + (cart.country_code || '(unknown)'),
'- gender: ' + gender,
'Cart:',
'- items: ' + (itemsSummary || '(unspecified items)'),
'- item_count: ' + items.length,
'- total: ' + total_display + '   <- write the total EXACTLY like this, do not reformat it',
'Touch:',
'- touch_number: ' + touch,
'- discount_code: ' + (touch === 2 ? cfg.discount_code : ''),
'',
'',
REGISTER_NOTE[register_zone],
'',
GENDER_NOTE[gender],
'',
'Write the message body now.'
].join('\n');

// ---------------------------------------------------------------------------
// SESSION OR TEMPLATE? (2026-09-03)
//
// WhatsApp lets a business reply free-form for 24 hours after the customer's
// last inbound message. Outside that window a production deployment must send a
// Meta-approved TEMPLATE, and pays per message for it.
//
// RECORDED, NOT ACTED ON. This is deliberate: the Twilio sandbox has no
// templates at all, so every message this build sends is already free-form. A
// second send branch here would be a limb no test could ever exercise
// differently, which is worse than no branch. What the classification buys is a
// real cost model in the daily digest instead of an estimate, and the field a
// client deployment needs on the day it does have templates.
//
// It is a LOWER BOUND on the true window, and that is the safe direction. The
// service window belongs to the conversation with the BUSINESS NUMBER, and this
// build shares one Twilio sandbox number across three case studies - a reply the
// router hands to Case 1 opens the real window without stamping any Case 2 cart.
// So this can call a session send a template, never the reverse, and the error
// costs an over-estimate of template spend rather than a compliance breach.
const SESSION_WINDOW_HOURS = 24;
let hours_since_inbound = null;
if (cart.last_inbound_at) {
  const inboundMs = Date.parse(cart.last_inbound_at);
  if (!isNaN(inboundMs)) {
    hours_since_inbound = Math.round(((Date.now() - inboundMs) / 3600000) * 10) / 10;
  }
}
const message_class = (hours_since_inbound !== null && hours_since_inbound < SESSION_WINDOW_HOURS)
  ? 'session' : 'template';

return [{ json: {
  anthropic_body: {
    model: 'claude-sonnet-5',
    // Sonnet 5 runs ADAPTIVE THINKING when `thinking` is omitted (Sonnet 4.6 ran
    // thinking-off), and max_tokens caps thinking + text TOGETHER. On 2026-08-04
    // that combination silently broke this node: the model spent all 400 output
    // tokens on a thinking block, emitted no text block at all, and every touch
    // fell back to the static template. Writing a 320-character WhatsApp message
    // does not need reasoning, so thinking is disabled explicitly rather than
    // left to the default.
    thinking: { type: 'disabled' },
    output_config: { effort: 'low' },
    // Headroom over the 320-char body budget. Sonnet 5's tokenizer produces ~30%
    // more tokens than Sonnet 4.6 for the same text, and Arabic is denser still.
    max_tokens: 1000,
    system: system,
    messages: [{ role: 'user', content: user }]
  },
  touch_number: touch,
  message_class: message_class,
  hours_since_inbound: hours_since_inbound,
  language: lang,
  total_display: total_display,
  register_zone: register_zone,
  customer_gender: gender,
  raw_total_digits: (cart.cart_total === null || cart.cart_total === undefined) ? null : String(Math.round(Number(cart.cart_total))),
  items_summary: itemsSummary,
  item_count: items.length,
  first_name: displayName,
  first_name_source: (displayName === firstName) ? 'as_stored' : 'arabic_lookup',
  discount_code: touch === 2 ? cfg.discount_code : null
} }];

const cart = $('Classify Conversion Result').first().json;
const req  = $('Build Touch Message Request').first().json;
const cfg  = $('Set Sweep Config').first().json;

const touch = req.touch_number;
const lang  = req.language;
const tlang = (lang === 'mixed') ? 'ar' : lang;
const name  = req.first_name;
const money = req.total_display;   // already formatted: '42,663,000 LBP'
const first = (Array.isArray(cart.cart_items) && cart.cart_items[0] && cart.cart_items[0].title)
  ? cart.cart_items[0].title : null;

let body = '';
let degraded = true;
let degradeReason = 'no_response';
try {
  const data = $input.first().json;
  const d = (data && data.body) ? data.body : data;
  if (d && Array.isArray(d.content)) {
    const tb = d.content.find(function (b) { return b && b.type === 'text' && b.text; });
    if (tb) {
      body = tb.text.toString().trim();
      if (body) { degraded = false; degradeReason = null; }
    } else {
      // A 200 with content but NO text block. Seen on 2026-08-04: Sonnet 5 spent
      // the entire max_tokens budget on a thinking block and produced no text.
      // 'no_response' hid that - it reads as an API failure when the API was
      // fine. Name the block types and the stop reason so the next occurrence is
      // diagnosable from the run log instead of the execution data.
      const kinds = d.content.map(function (b) { return (b && b.type) || 'unknown'; }).join(',');
      degradeReason = ('no_text_block: stop=' + (d.stop_reason || '?') +
                       ' blocks=[' + (kinds || 'empty') + ']').slice(0, 200);
    }
