    degradeReason = ('api_error: ' + JSON.stringify(d.error)).slice(0, 200);
  }
} catch (e) { degradeReason = 'parse_error'; }

// A model that ignored the instruction and wrote its own link would produce a
// message with two links, one of them possibly wrong. Fall back instead.
if (!degraded && /https?:\/\//i.test(body)) { degraded = true; degradeReason = 'model_wrote_a_url'; }

// The total is formatted in code and handed to the model ready to use. If the
// raw digit run appears instead (42663000 rather than 42,663,000) the model
// reformatted it, which is exactly the unreadable output this rule exists to
// prevent. Applies in every language.
if (!degraded && req.raw_total_digits && req.raw_total_digits.length > 3 &&
    body.indexOf(req.raw_total_digits) !== -1) {
  degraded = true; degradeReason = 'unformatted_amount';
}

// Arabic formality is enforced in code, not left to the prompt. Prompt v1 and v2
// both produced inconsistent register on the same customer profile - v2 reliably
// produced حضرتك but still wrote informal-feminine verbs beside it
// (سلتك محفوظة لحضرتك متى أردتِ), which is internally inconsistent in formal Arabic.
// Same reasoning as appending the recovery link and the STOP line ourselves:
// anything that must be right every time does not belong to the model.
//
// Deliberately HIGH-PRECISION rather than exhaustive. Over-matching would send
// every Arabic customer a static template and quietly delete the personalisation
// that is the point of the feature, so this flags only unambiguous markers.
// Arabic letter range \u0621-\u064A is used for word boundaries because JS \b is ASCII-only.
if (!degraded && (tlang === 'ar')) {
  const AR = '\u0621-\u064A';
  // 2nd-person feminine PAST stems, shared by the kasra carve-out below and by
  // rule 10. One list, because a stem the checker tolerates a kasra on is exactly
  // a stem it must reject a \u064a on. Known limitation, deliberately accepted: for some
  // stems this shape is also a 1st-person possessive noun - \u0631\u063a\u0628\u062a\u064a can mean "my
  // desire". A false positive costs the personalisation and still sends the
  // respectful template, so it is the cheap direction to be wrong in. \u062d\u0641\u0638 is kept
  // out for the same reason it always was: \u062d\u0641\u0638\u062a\u0647\u0627 is the STORE speaking.
  const FEM_PAST_STEMS = ['\u0631\u063a\u0628\u062a','\u062a\u0631\u0643\u062a','\u0627\u062e\u062a\u0631\u062a','\u0623\u0636\u0641\u062a',
    '\u0623\u0631\u062f\u062a','\u0632\u0631\u062a','\u0627\u0634\u062a\u0631\u064a\u062a','\u0637\u0644\u0628\u062a','\u0648\u0636\u0639\u062a',
    '\u0623\u0643\u0645\u0644\u062a','\u0646\u0633\u064a\u062a','\u0628\u062f\u0623\u062a'];

  const MARKERS = [
    { re: new RegExp('(^|[^' + AR + '])\u0623\u0646\u062A[\u0650\u064E]?([^' + AR + ']|$)'), tag: 'informal_pronoun' },
