  // Approved CTAs are masked out before the markers run, NOT removed from the
  // marker list. arabic-master-reference.md section 8.2 marks أكمل طلبك and أتم عملية الشراء
  // canonical, and Hussein whitelisted them 2026-08-07 - but أكمل on its own is
  // still an informal imperative everywhere else in the message. Masking keeps
  // both true. They are fixed strings: never inflected, not even for gender.
  const APPROVED_CTA = [
    '\u0623\u0643\u0645\u0644 \u0637\u0644\u0628\u0643',
    '\u0623\u062a\u0645 \u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u0634\u0631\u0627\u0621'
