  let scanned = body;
  for (const cta of APPROVED_CTA) scanned = scanned.split(cta).join(' ');

  // KASRA CARVE-OUT - ruled by Hussein 2026-09-08, and deliberately the narrowest
  // shape that satisfies the ruling. The MSA 2nd-person feminine past is written
  // \u062a\u0631\u0643\u062a\u0650 with a final kasra; the no-vowel-marks marker bans every short
  // vowel, and was added on 2026-08-04 precisely because a vowelled \u0627\u062e\u062a\u0631\u062a\u0650
  // was indistinguishable from the form section 1.1 called correct. Both rulings
  // stand: the kasra is stripped from `scanned` - so the vowel-mark marker never
  // sees it - ONLY at the END of a known feminine-past stem AND ONLY when the
  // cart's gender is female. A kasra anywhere else, or on a male or unknown cart,
  // still degrades. Same masking technique as APPROVED_CTA above, and for the same
  // reason: it keeps two true rules true without arbitrating between them.
  if (req.customer_gender === 'female') {
    const femKasra = new RegExp('(^|[^' + AR + '])([\\u0648\\u0641]?(?:' + FEM_PAST_STEMS.join('|') + '))\\u0650(?![' + AR + '])', 'g');
    scanned = scanned.replace(femKasra, '$1$2');
  }

  const hits = [];
  for (const m of MARKERS) {
    // RULE 8 IS FEMALE-ONLY. Ruled by Hussein 2026-08-31 after the first live
    // male-customer generation. For a male addressee the same spelling IS the
    // correct 2nd-person masculine form, and unvowelled it is identical to the
    // feminine-missing-ya form this rule was written to catch - so applying it
    // to every cart degraded every Arabic message to a male customer down to
    // the static template. Observed live 2026-08-28 on cart f75d8d6a
    // (customer_gender male, degrade_reason feminine_suffix_missing_ya) - the
    // first Arabic touch this system ever generated for a man.
    //
    // Deliberate consequence of 'female only' rather than 'not male': a cart
    // whose gender is `unknown` is NOT checked by this rule. `unknown` already
    // means the model was asked for gender-neutral phrasing, and rule 7b still
    // rejects feminine present forms there.
    if (m.female_only && req.customer_gender !== 'female') continue;
