  // Banned by global CLAUDE.md, by arabic-master-reference.md §7 (Religious phrasing) and by
  // style guide §3 - three documents - and until 2026-08-07 it was enforced by
  // NONE of them: the line had silently dropped out of the deployed system
  // prompt while touch-message-generator.md still claimed it was there, and no
  // marker ever existed. Found by reading the running prompt against the file.
  // Matches the common spellings, with or without the alef-hamza and the space.
  const RELIGIOUS = /(^|[^ء-ي])[وف]?إ?ا?ن\s?شاء\s?الله/;
