  // حضرتك اخترت / لو رغبت  ->  right.   حضرتك اخترتي / لو رغبتي  ->  wrong.
  // Requires the ي to be at a word boundary, so the pronoun-suffixed form ruled
  // CORRECT in 1.1a (حضرتك تركتيهما) does not match here and rule 8 does not
  // match it either. The two rules are complements, not overlaps.
  //
  // Known limitation, deliberately accepted (same treatment as حفظ in rule 8):
  // for some stems this shape is also a first-person possessive noun - رغبتي can
  // mean "my desire". A false positive costs the personalisation and still sends
  // the respectful template, so it is the cheap direction to be wrong in.
  const OBJ_PRONOUN = '(?:\\u0647\\u0645\\u0627|\\u0647\\u0645|\\u0647\\u0646|\\u0647\\u0627|\\u0647)?';
  const bareYa = new RegExp('(^|[^' + AR + '])[\\u0648\\u0641]?(' + FEM_PAST_STEMS.join('|') + ')\\u064a' + OBJ_PRONOUN + '(?![' + AR + '])');
  if (bareYa.test(scanned)) hits.push('bare_feminine_ya');

  // RULE 12 - COLLOQUIAL / DIALECT VOCABULARY.
  // Ruled by Hussein 2026-09-01, on the first model-generated Arabic message this
  // system ever delivered: `طلبك بانتظارك متى حبيت تكمل الطلب`. حبيت is Levantine
  // for "you liked/wanted"; MSA wants متى شئت or متى رغبت. The message passed all
  // eleven existing rules because NONE of them look at vocabulary - they check
  // pronouns, imperatives, agreement, vowel marks and religious phrasing. A
  // dialect word is exactly as wrong as an informal pronoun and was unguarded.
  //
  // High-precision list, same policy as every other marker here: only tokens that
  // cannot be defended as MSA in any position. Words that are merely COMMON in
  // speech but valid in MSA are deliberately absent.
  const DIALECT = ['حبيت','بدك','بدي','بدها',
    'عايز','عاوز','شو','ليش','هلق',
    'هلأ','كتير','منيح','يلا','بكرا',
    'لسا','هيك','منشان'];
  const dialect = new RegExp('(^|[^' + AR + '])(' + DIALECT.join('|') + ')(?![' + AR + '])');
  if (dialect.test(scanned)) hits.push('colloquial_dialect_word');

  // RULE 13 - GREETING STACKED WITH حضرتك.
  // Ruled by Hussein 2026-09-01, same message: `مرحباً حضرتك حسين`. The honorific
  // and the name must not be stacked in the greeting. Correct is the bare name
  // (مرحباً حسين) or the prepositional form (مرحباً بحضرتك); حضرتك belongs later in
  // the sentence, where rule `missing_respectful_form` still requires it.
  //
  // Anchored on the GREETING, not on the name: the model transliterates, so the
  // cart's `Hussein` arrived as حسين and matching req.first_name would have missed
  // it entirely. مرحباً بحضرتك does not match - the بـ is attached, so the
  // whitespace-then-حضرتك sequence never occurs.
  const GREET_HADRETAK = /(مرحبا|أهلا|اهلا)ً?\s+حضرتك/;
  if (GREET_HADRETAK.test(scanned)) hits.push('greeting_stacked_with_hadretak');

  // Agreement after حضرتك. Corrected 2026-08-03 by Hussein (native speaker):
  // حضرتك is a POLITE SECOND PERSON in real MENA usage, so the verb stays in the
  // 2nd person - حضرتك اخترت, NOT حضرتك اختارت and NOT حضرتك اختار.
  //
  // My first attempt encoded it as a 3rd-person noun phrase and only looked
  // right because تركت is spelled identically for 2nd person and 3rd feminine in
  // unvowelled text. Hollow verbs expose the difference: اختار -> اخترت (2nd)
  // vs اختارت (3rd fem). See prompts/arabic-style-guide.md.
  //
  // Arabic morphology cannot be parsed properly with a regex, so this is
  // deliberately narrow: حضرتك immediately followed by a 3rd-person form that is
  // DISTINGUISHABLE in script. Verbs whose 2nd-person and 3rd-feminine forms are
  // identical (تركت, طلبت, وضعت...) are intentionally not flagged - they are not
  // errors, they are ambiguous.
  // 3rd-person MASCULINE (he left / he chose ...)
  const THIRD_MASC = ['\u062A\u0631\u0643', '\u0627\u062E\u062A\u0627\u0631',
    '\u0623\u0636\u0627\u0641', '\u0646\u0633\u064A', '\u0637\u0644\u0628',
    '\u0648\u0636\u0639', '\u0628\u062F\u0623', '\u0623\u0643\u0645\u0644',
    '\u0634\u0627\u0647\u062F', '\u0632\u0627\u0631', '\u062D\u0641\u0638',
    '\u0623\u0631\u0627\u062F', '\u0627\u0634\u062A\u0631\u0649'];
  // 3rd-person FEMININE, but only the forms that differ in script from the
  // correct 2nd-person form: اختارت vs اخترت, أضافت vs أضفت, أرادت vs أردت,
  // اشترت vs اشتريت, زارت vs زرت.
  const THIRD_FEM = ['\u0627\u062E\u062A\u0627\u0631\u062A', '\u0623\u0636\u0627\u0641\u062A',
    '\u0623\u0631\u0627\u062F\u062A', '\u0627\u0634\u062A\u0631\u062A', '\u0632\u0627\u0631\u062A'];
  const WRONG_AGREEMENT = THIRD_FEM.concat(THIRD_MASC);   // longest first matters
  const agree = new RegExp('\u062D\u0636\u0631\u062A\u0643\\s+(' + WRONG_AGREEMENT.join('|') + ')(?![' + AR + '])');
  if (agree.test(scanned)) hits.push('verb_agreement_after_hadretak');
  // حضرتك is required only in the markets where it is natural (Hussein,
  // 2026-08-04). Requiring it in the Gulf would force an Egyptian/Levantine
  // honorific on a Khaleeji customer - the opposite of correct. Informality is
  // still blocked everywhere by the markers above.
  if (req.register_zone === 'levant_egypt' &&
      body.indexOf('\u062D\u0636\u0631\u062A\u0643') === -1) hits.push('missing_respectful_form');
  if (hits.length) { degraded = true; degradeReason = 'informal_arabic:' + hits.join('+'); }
}

// Static fallbacks: a slightly generic reminder beats silence, and the link is
// the part that actually recovers the cart.
const item = first ? first : (tlang === 'ar' ? 'طلبك' : (tlang === 'fr' ? 'votre article' : 'your item'));
const FALLBACK = {
  ar: {
    1: (name ? ('مرحباً ' + name + '، ') : 'مرحباً، ') + 'السلة الخاصة بحضرتك (' + item + ') لا تزال محفوظة لدينا بقيمة ' + money + '. يمكن إتمام الطلب في أي وقت يناسب حضرتك.',
    2: (name ? ('مرحباً ' + name + '، ') : 'مرحباً، ') + 'السلة الخاصة بحضرتك (' + item + '، ' + money + ') لا تزال محفوظة. هدية منا: كود الخصم ' + cfg.discount_code + '.',
    3: (name ? ('مرحباً ' + name + '، ') : 'مرحباً، ') + 'هذه آخر رسالة بخصوص السلة الخاصة بحضرتك (' + item + '، ' + money + '). ستبقى محفوظة إن رغبت حضرتك في إتمام الطلب.'
  },
  fr: {
    1: (name ? ('Bonjour ' + name + ', ') : 'Bonjour, ') + 'votre panier (' + item + ') est bien enregistré, ' + money + '. Vous pouvez finaliser quand vous voulez.',
    2: (name ? ('Bonjour ' + name + ', ') : 'Bonjour, ') + 'votre panier (' + item + ', ' + money + ') vous attend. Un cadeau de notre part : le code ' + cfg.discount_code + '.',
    3: (name ? ('Bonjour ' + name + ', ') : 'Bonjour, ') + 'dernier message au sujet de votre panier (' + item + ', ' + money + '). Il reste enregistré si vous souhaitez finaliser.'
  },
  en: {
    1: (name ? ('Hi ' + name + ', ') : 'Hello, ') + 'your cart (' + item + ', ' + money + ') is still saved. You can finish checking out whenever suits you.',
    2: (name ? ('Hi ' + name + ', ') : 'Hello, ') + 'your cart (' + item + ', ' + money + ') is still waiting. A gift from us: use code ' + cfg.discount_code + '.',
    3: (name ? ('Hi ' + name + ', ') : 'Hello, ') + 'last message about your cart (' + item + ', ' + money + '). It stays saved if you would like to complete it.'
  }
};

if (degraded) body = (FALLBACK[tlang] || FALLBACK.en)[touch] || (FALLBACK.en[1]);

// Body budget so body + link + opt-out line stays under the 500-char cap (spec 6).
function clip(s, n) {
  if (s.length <= n) return s;
  const cut = s.slice(0, n);
  const sp = cut.lastIndexOf(' ');
  return (sp > n * 0.6 ? cut.slice(0, sp) : cut).trim() + '…';
}
body = clip(body, 320);

const STOP = {
  // Canonical opt-out instruction, arabic-master-reference.md §8.5 (vetted [OK] 2026-08-07).
  // Replaces the earlier ad-hoc 'للإيقاف أرسل: توقف'. The quotes around the
  // keyword are why `Resolve Reply Context` in workflow 03 now strips quote
  // characters before matching - otherwise a customer who copies the keyword
  // back verbatim would not be recognised as opting out.
  ar: 'لإيقاف الرسائل، أرسل "توقف"',
  en: 'Reply STOP to unsubscribe.',
  fr: 'Répondez STOP pour vous désabonner.'
};

// ---------------------------------------------------------------------------
// THE RECOVERY LINK OPENS IN THE CUSTOMER'S OWN LANGUAGE (2026-09-03).
//
// Shopify's abandoned_checkout_url carries the locale of the storefront the
// shopper happened to browse. On a single-language store that is en-LB for
// EVERY customer, so a carefully-written Arabic message ended in a link that
// opened an English checkout - the one moment in the whole sequence where the
// customer is asked to act.
//
// TWO GUARDS, both there to protect the link rather than the language:
//
// 1. REWRITE ONLY, NEVER CONSTRUCT. A URL with no locale parameter is returned
//    byte-identical. Shopify also expresses locale as a PATH PREFIX in some
//    configurations, and synthesising one of those would produce a 404 on the
//    single most load-bearing element of the message.
//
// 2. ONLY A LOCALE THE STORE PUBLISHES. Shopify serves a locale only when it is
//    a published storefront language; asking for an unpublished one degrades
//    the link instead of translating it. PUBLISHED_LOCALES is therefore an
//    explicit allow-list of what THIS store publishes, not a list of languages
//    the system supports. Adding a language to the store means adding it here
//    too - and until then the customer gets a working link in the wrong
//    language, which beats a broken one in the right language.
//
// The region subtag is preserved (en-LB -> ar-LB), because it drives currency
// and shipping presentment and has nothing to do with the language.
// ---------------------------------------------------------------------------
const PUBLISHED_LOCALES = ['en', 'ar'];

function localizeRecoveryUrl(u, wantLang) {
  if (!u) return { url: '', locale: null, changed: false };
  const m = u.match(/([?&]locale=)([A-Za-z]{2})(-[A-Za-z0-9]+)?/);
  if (!m) return { url: u, locale: null, changed: false };
  const had = m[2] + (m[3] || '');
  if (PUBLISHED_LOCALES.indexOf(wantLang) < 0) return { url: u, locale: had, changed: false };
  if (m[2].toLowerCase() === wantLang) return { url: u, locale: had, changed: false };
  const want = wantLang + (m[3] || '');
  return { url: u.replace(m[0], m[1] + want), locale: want, changed: true };
}

const loc = localizeRecoveryUrl(cart.recovery_url || '', tlang);
const url = loc.url;
let message = body;
if (url) message += '\n' + url;
// Opt-out instruction on touch 1 only (spec 7). Appended deterministically -
// compliance controls are not left to a language model.
if (touch === 1) message += '\n' + (STOP[tlang] || STOP.en);

// Absolute guard.
if (message.length > 500) {
  const overflow = message.length - 500;
  body = clip(body, Math.max(40, 320 - overflow - 1));
  message = body + (url ? ('\n' + url) : '') + (touch === 1 ? ('\n' + (STOP[tlang] || STOP.en)) : '');
}

return [{ json: {
  message: message,
  message_chars: message.length,
  message_degraded: degraded,
  degrade_reason: degradeReason,
  touch_number: touch,
  language: lang,
  total_display: req.total_display,
  register_zone: req.register_zone,
  raw_total_digits: (cart.cart_total === null || cart.cart_total === undefined) ? null : String(Math.round(Number(cart.cart_total))),
  message_class: req.message_class,
  hours_since_inbound: req.hours_since_inbound,
  recovery_url_locale: loc.locale,
  recovery_url_localized: loc.changed,
  has_recovery_url: !!url
} }];

const sent = $('Send WhatsApp Touch (Twilio)').first().json;
const resp = $input.first().json;

// Twilio issues a SID the moment it ACCEPTS a message; delivery is attempted
// afterwards. On 2026-08-03 that difference cost three touches: every message
// came back `queued` with `error_code: null`, and all three later failed with
// 63015 (recipient not joined to the WhatsApp sandbox). Because the workflow
// counted the touch at acceptance, three customers who received nothing each
// had one of their three permitted touches spent. The touch is therefore now
// committed only after re-reading the message resource.
let status = null, errCode = null, detail = null, polled = false;
try {
  // Do NOT use this workflow's usual `resp.body ? resp.body : resp` unwrap here.
  // That idiom strips n8n's fullResponse envelope, but a Twilio Message resource
  // has its OWN `body` field holding the message TEXT - so the unwrap silently
  // replaced the object with a string and every poll came back 'unknown'.
  // `Check Delivery Status` does not set fullResponse, so this IS the resource.
  const d = resp;
  if (d && d.sid) {
    status = d.status || null;
    errCode = (d.error_code !== undefined) ? d.error_code : null;
    polled = true;
  } else if (d && d.error) {
    detail = ('status_poll_failed: ' + JSON.stringify(d.error)).slice(0, 200);
  } else {
    detail = ('status_poll_unrecognised: ' + JSON.stringify(d === null || d === undefined ? {} : d)).slice(0, 200);
  }
} catch (e) { detail = 'status_poll_exception'; }

const HARD_FAIL = ['failed', 'undelivered'];
const failed = polled && HARD_FAIL.indexOf(String(status)) >= 0;

// ---------------------------------------------------------------------------
// THREE OUTCOMES, NOT TWO (2026-09-03).
//
// Until now every delivery failure took the same path: push next_touch_at +2h
// and try again. For a number with no WhatsApp account at all that is an
// infinite loop - the cart never closes, it sits in the open queue for the full
// 30-day lookback, and it drags the recovery rate down as though the COPY had
// failed. A failure now has to say which kind it is.
//
// TERMINAL - the recipient cannot receive from us at all. Close the cart.
//   63003  Channel could not find To address (not a registered WhatsApp user)
//   63024  Invalid message recipient - Meta reports an invalid WhatsApp user or
//          a recipient-side restriction
//   63015  Sandbox can only message numbers that have joined it. Sandbox-only,
//          so it cannot occur on a production WABA, and on the demo rig it means
//          exactly "we cannot reach this handset" - the same answer.
//
// SLOW RETRY - a real ceiling, not a dead number. Retrying in 2h only buys
// another failure, so back off a full day instead.
//   131049 Meta declined to deliver a MARKETING template to protect the user's
//          engagement quality: the per-user frequency cap. Meta's own guidance
//          is to wait at least 24h. Treating this as terminal would write off a
//          perfectly good customer over a rate limit.
//   63038  OUR account exceeded its own daily message allowance. Nothing to do
//          with this customer.
//
// EVERYTHING ELSE keeps the +2h retry it has always had, including 63005 and
// 63021: those look recipient-shaped but also fire on OUR malformed content,
// and closing a customer's cart because we sent bad markup is the wrong
// direction. Unknown codes retry too - locked decision #4 is silence over a
// wrong message, and guessing wrong here costs a few extra retries rather than
// a customer written off.
// ---------------------------------------------------------------------------
const TERMINAL_CODES     = [63003, 63015, 63024];
const SLOW_RETRY_CODES   = [131049, 63038];
const SLOW_RETRY_MINUTES = 1440;

const code  = (errCode === null || errCode === undefined || errCode === '') ? null : Number(errCode);
const known = (code !== null && !isNaN(code));

const terminal  = failed && known && TERMINAL_CODES.indexOf(code) >= 0;
const slowRetry = !terminal && known && SLOW_RETRY_CODES.indexOf(code) >= 0;

// If OUR OWN poll failed, that is not evidence the customer missed the message.
// Unknown is not failed: the touch stands, and the run log carries
// delivery_status 'unknown' so a systematically broken poll stays visible.
return [{ json: {
  send_ok: !failed,
  delivery_terminal: terminal,
  retry_after_minutes: slowRetry ? SLOW_RETRY_MINUTES : null,
  delivery_status: polled ? status : 'unknown',
  delivery_error_code: errCode,
  delivery_detail: detail,
  twilio_sid: sent ? (sent.sid || null) : null
} }];

const resp = $input.first().json;
const httpCode = (resp && resp.statusCode) ? resp.statusCode : 0;
const rows = (httpCode === 200 && Array.isArray(resp.body)) ? resp.body : [];
const n = (step) => rows.filter(r => r.step_name === step).length;

const sent       = n('touch_sent');
const deferred   = n('touch_deferred_send_window');
const closed     = n('cart_closed_converted');
const skipped    = n('conversion_check_failed');
const sendFailed = n('twilio_send_failed');
const fetchFail  = n('fetch_due_carts_failed');
// Carts closed because the number cannot receive WhatsApp (2026-09-03). Counted
// here or carts_processed silently under-reports every sweep that meets one -
// the cart WAS processed, it just ended somewhere new.
const undeliverable = n('cart_closed_undeliverable');
const rowsFailed  = rows.filter(r => r.status === 'failed').length;
const rowsPartial = rows.filter(r => r.status === 'partial').length;

// Observability that cannot read itself is not observability. If the read-back
// failed we do NOT report a clean sweep - we say so and alert.
const readable = httpCode === 200;

const summary = {
  carts_processed: sent + deferred + closed + skipped + sendFailed + undeliverable,
  touches_sent: sent,
  deferred: deferred,
  closed_converted: closed,
  closed_undeliverable: undeliverable,
  skipped_api_failure: skipped,
  send_failures: sendFailed,
  fetch_failed: fetchFail,
  rows_failed: rowsFailed,
  rows_partial: rowsPartial,
  summary_source: readable ? 'run_logs' : ('unavailable_http_' + httpCode)
};

// undeliverable is deliberately NOT part of `degraded`. A dead number is a
// normal outcome of running a recovery campaign, not a fault in this system,
// and alerting on it would page the owner for something they cannot fix. It is
// reported in the summary and counted in the daily digest instead.
const degraded = !readable || rowsFailed > 0 || skipped > 0 || sendFailed > 0 || fetchFail > 0;

let headline;
if (!readable) {
  headline = 'Sweep finished but its own run_logs could not be read (HTTP ' + httpCode + ') - state unknown';
} else if (fetchFail > 0) {
  headline = 'Sweep could not read the cart queue - no carts were processed';
} else {
  const bits = [];
  if (skipped > 0)    bits.push(skipped + ' cart(s) skipped: Shopify conversion check failed');
  if (sendFailed > 0) bits.push(sendFailed + ' send failure(s) - touch NOT counted, retrying');
  if (rowsFailed > 0 && bits.length === 0) bits.push(rowsFailed + ' failed step(s)');
  headline = bits.join(' | ');
}

const fields = [
  { type: 'mrkdwn', text: '*Carts processed:*\n' + summary.carts_processed },
  { type: 'mrkdwn', text: '*Touches sent:*\n' + sent },
  { type: 'mrkdwn', text: '*Skipped (Shopify unknown):*\n' + skipped },
  { type: 'mrkdwn', text: '*Send failures:*\n' + sendFailed },
  { type: 'mrkdwn', text: '*Deferred (window/prayer/age):*\n' + deferred },
  { type: 'mrkdwn', text: '*Closed as converted:*\n' + closed },
  { type: 'mrkdwn', text: '*Closed as undeliverable:*\n' + undeliverable }
];

const errs = rows.filter(r => r.status === 'failed' && r.error_message).slice(0, 3)
  .map(r => '- ' + r.step_name + ': ' + String(r.error_message).slice(0, 160)).join('\n');

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Sweep degraded - 02 Verifier & Touch Sender', emoji: false } },
  { type: 'section', text: { type: 'mrkdwn', text: headline || 'Degraded' } },
  { type: 'section', fields: fields }
];
if (errs) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Errors:*\n```' + errs + '```' } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'Execution ' + $execution.id + ' - no customer was messaged on any skipped cart (fail-safe: silence over a wrong message).' }] });

return [{ json: {
  degraded: degraded,
  summary: summary,
  slack_body: { channel: '#automation-errors', text: 'Sweep degraded: ' + (headline || 'see run_logs'), blocks: blocks }
} }];
